begin; update public.lx_catalog set payload=payload||jsonb_build_object('archived',true,'archivedPublished',published,'archiveReason','catalog-reset-20261030','archivedAt',now()),published=false,updated_at=now() where payload->>'type' in ('Filme','Música') and coalesce((payload->>'archived')::boolean,false)=false; update public.lx_auto_discovery set published=false where media_kind in ('films','music','music_metadata') and published=true; commit; select coalesce(payload->>'type','?') type,count(*) filter(where published) visible,count(*) filter(where payload->>'archived'='true') archived from public.lx_catalog group by 1 order by 1;
